1	// How a scenario unfolds. This module knows the order events happen in and
2	// what each step leaves behind for the next one; it delegates the question of
3	// what anything costs to pricing.ts.
4	
5	import {
6	  insuranceSumOf,
7	  premiumFor,
8	  type Customer,
9	  type Item,
10	} from "./pricing.js";
11	
12	export type { Customer, KnownItemType } from "./pricing.js";
13	
14	export interface Scenario {
15	  customer: Customer;
16	  steps: Step[];
17	}
18	
19	export interface QuoteStep {
20	  op: "quote";
21	  items: Item[];
22	}
23	
24	export interface Damage {
25	  itemType: string;
26	  amount: number;
27	}
28	
29	export interface ClaimStep {
30	  op: "claim";
31	  policy: number;
32	  incident: { cause: string; damages: Damage[] };
33	}
34	
35	export type Step = QuoteStep | ClaimStep;
36	
37	export interface ScenarioResults {
38	  results: ({ premium: number } | { payout: number; remainingCap: number })[];
39	}
40	
41	// What earlier steps have established by the time a later step is priced.
42	// Steps are not independent: a quote is a follow-up contract when the customer
43	// already took a quote earlier in the same scenario. Folding this forward —
44	// rather than re-deriving it from the step prefix — is what lets a step read
45	// the state its predecessors left behind.
46	interface Policy {
47	  remainingCap: number;
48	}
49	
50	interface ScenarioState {
51	  hasQuoted: boolean;
52	  // Keyed by the step index of the quote that created the policy, which is
53	  // how a later claim step refers to it.
54	  policies: Map<number, Policy>;
55	}
56	
57	const INITIAL_STATE: ScenarioState = { hasQuoted: false, policies: new Map() };
58	
59	type StepOutcome = ScenarioResults["results"][number];
60	
61	interface StepRun {
62	  outcome: StepOutcome;
63	  state: ScenarioState;
64	}
65	
66	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
67	
68	const runQuote = (
69	  { items }: QuoteStep,
70	  customer: Customer,
71	  state: ScenarioState,
72	  index: number,
73	): StepRun => ({
74	  outcome: {
75	    premium: premiumFor(items, {
76	      customer,
77	      isFollowUpContract: state.hasQuoted,
78	    }),
79	  },
80	  state: {
81	    ...state,
82	    hasQuoted: true,
83	    policies: new Map(state.policies).set(index, {
84	      remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items),
85	    }),
86	  },
87	});
88	
89	const DEDUCTIBLE_PER_DAMAGE = 100;
90	
91	const payoutForDamage = (damage: Damage): number =>
92	  damage.amount - DEDUCTIBLE_PER_DAMAGE;
93	
94	const runClaim = (step: ClaimStep, state: ScenarioState): StepRun => {
95	  const policy = state.policies.get(step.policy)!;
96	  const payout = step.incident.damages.reduce(
97	    (total, damage) => total + payoutForDamage(damage),
98	    0,
99	  );
100	  const remainingCap = policy.remainingCap - payout;
101	
102	  return {
103	    outcome: { payout, remainingCap },
104	    state: {
105	      ...state,
106	      policies: new Map(state.policies).set(step.policy, { remainingCap }),
107	    },
108	  };
109	};
110	
111	// Dispatches a step to its handler. Written as an exhaustive switch on `op`
112	// so that adding a step kind to the Step union turns "I forgot to handle it"
113	// into a compile error rather than a wrong number.
114	const runStep = (
115	  step: Step,
116	  customer: Customer,
117	  state: ScenarioState,
118	  index: number,
119	): StepRun => {
120	  switch (step.op) {
121	    case "quote":
122	      return runQuote(step, customer, state, index);
123	    case "claim":
124	      return runClaim(step, state);
125	  }
126	};
127	
128	export const runScenario = ({ customer, steps }: Scenario): ScenarioResults => {
129	  const { results } = steps.reduce<{
130	    results: StepOutcome[];
131	    state: ScenarioState;
132	  }>(
133	    ({ results, state }, step, index) => {
134	      const stepRun = runStep(step, customer, state, index);
135	      return { results: [...results, stepRun.outcome], state: stepRun.state };
136	    },
137	    { results: [], state: INITIAL_STATE },
138	  );
139	
140	  return { results };
141	};
