  amount: number;
}

export interface ClaimStep {

const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;

const runQuote = (
  { items }: QuoteStep,
  customer: Customer,
  state: ScenarioState,
  index: number,
): StepRun => ({
  outcome: {
    premium: premiumFor(items, {
      customer,
      isFollowUpContract: state.hasQuoted,
    }),
  },
  state: {
    ...state,
    hasQuoted: true,
    policies: new Map(state.policies).set(index, {
      remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items),
    }),
  },
});

const DEDUCTIBLE_PER_DAMAGE = 100;

const payoutForDamage = (damage: Damage): number =>
  damage.amount - DEDUCTIBLE_PER_DAMAGE;

const runClaim = (step: ClaimStep, state: ScenarioState): StepRun => {
  const policy = state.policies.get(step.policy)!;
  const payout = step.incident.damages.reduce(
    (total, damage) => total + payoutForDamage(damage),
    0,
  );
  const remainingCap = policy.remainingCap - payout;

  return {
    outcome: { payout, remainingCap },
    state: {
      ...state,
      policies: new Map(state.policies).set(step.policy, { remainingCap }),
    },
  };
};

