// Every policy a step establishes is recorded the same way, so both handlers
// go through here rather than each rebuilding the map.
const withPolicy = (
  state: ScenarioState,
  index: number,
  policy: Policy,
): ScenarioState => ({
  ...state,
  policies: new Map(state.policies).set(index, policy),
});

const runQuote = (
  { items }: QuoteStep,
  customer: Customer,
  state: ScenarioState,
  index: number,
): StepRun => ({
  outcome: {
    premium: premiumFor(items, {
      customer,
      isFollowUpContract: state.hasQuoted,
    }),
  },
  state: withPolicy({ ...state, hasQuoted: true }, index, {
    remainingCap: capFor(items),
  }),
});

const runClaim = (
  { policy: policyIndex, incident }: ClaimStep,
  state: ScenarioState,
): StepRun => {
  // A claim always names a policy an earlier quote step created. Nothing
  // validates that yet — the test rejecting unknown references will force the
  // question of what to do when it is absent.
  const covered = state.policies.get(policyIndex) ?? { remainingCap: 0 };
  const payout = payoutForDamages(incident.damages);
  const remainingCap = covered.remainingCap - payout;

  return {
    outcome: { payout, remainingCap },
    state: withPolicy(state, policyIndex, { remainingCap }),
  };
};

